fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    // Separator is guaranteed to be non-empty.
    // maxsplit is the maximum number of right splits.
    // For each string in a, produce the list of parts by splitting from the right,
    // cutting at most maxsplit times, or none if maxsplit == 0.
    // If input string is empty, output should be a vec with a single empty string.
    
    a.into_iter()
        .map(|s| {
            if maxsplit == 0 {
                // no splitting, just one part: the original string
                vec![s]
            } else if s.is_empty() {
                // empty input string, return one empty string
                vec![String::new()]
            } else {
                // normal right split up to maxsplit times
                // rsplitn returns an iterator producing up to n items starting from the end
                // So rsplitn(maxsplit+1) produces at most maxsplit+1 parts.
                let parts: Vec<String> = s
                    .rsplitn((maxsplit as usize) + 1, &sep)
                    .map(|part| part.to_string())
                    .collect();
                parts
            }
        })
        .collect()
}